/*
 * Stylish — a Claude.ai-inspired theme for TiddlyWiki
 * Warm ivory surfaces, a soft clay accent, flat & calm.
 * Colours come from the active palette (Claude Light / Claude Dark).
 */

/* ---------------- Base page & typography ---------------- */
html body.tc-body {
	background-color: <<colour page-background>>;
	font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", Roboto, "Helvetica Neue", Arial, sans-serif;
	-webkit-font-smoothing: antialiased;
	text-rendering: optimizeLegibility;
}

/* ---------------- Story river ---------------- */
.tc-story-river {
	padding-top: 28px;
}

/* ---------------- The tiddler card (flat & warm) ---------------- */
.tc-tiddler-frame {
	border: 1px solid <<colour tiddler-border>>;
	border-radius: 14px;
	padding: 26px 32px 28px;
	margin-bottom: 22px;
	box-shadow: 0 1px 2px rgba(60,50,40,0.04);
	transition: box-shadow .25s ease, border-color .25s ease;
}
.tc-tiddler-frame:hover {
	box-shadow: 0 2px 10px -4px rgba(60,50,40,0.12);
}
.tc-tiddler-frame.tc-tiddler-edit-frame {
	box-shadow: 0 0 0 2px <<colour primary>>, 0 2px 10px -4px rgba(60,50,40,0.12);
}

/* ---------------- Titles ---------------- */
.tc-tiddler-title {
	margin-bottom: 14px;
}
.tc-tiddler-title .tc-titlebar h2 {
	font-weight: 700;
	font-size: 1.4em;
	letter-spacing: -0.01em;
	line-height: 1.25;
}
.tc-site-title {
	font-weight: 700;
	font-size: 1.9em;
	letter-spacing: -0.02em;
	margin-bottom: 4px;
}

/* ---------------- Body copy ---------------- */
.tc-tiddler-body {
	font-size: 1.02em;
	line-height: 1.7;
}
.tc-tiddler-body > p:first-child { margin-top: 0; }
.tc-tiddler-body h1,
.tc-tiddler-body h2,
.tc-tiddler-body h3,
.tc-tiddler-body h4 {
	letter-spacing: -0.01em;
	line-height: 1.3;
	margin-top: 1.6em;
}

/* ---------------- Links (body & popups only) ---------------- */
.tc-tiddler-body a.tc-tiddlylink,
.tc-drop-down a.tc-tiddlylink {
	color: <<colour primary>>;
	text-decoration: none;
	border-bottom: 1px solid transparent;
	transition: border-color .15s ease, color .15s ease;
}
.tc-tiddler-body a.tc-tiddlylink:hover {
	border-bottom-color: <<colour primary>>;
}
.tc-tiddler-body a.tc-tiddlylink-missing {
	font-style: italic;
	opacity: .85;
}

/* ---------------- Tag pills (soft sand chips) ---------------- */
.tc-tag-label {
	border-radius: 999px;
	padding: 0.2em 0.75em;
	font-size: 0.78em;
	font-weight: 600;
	letter-spacing: 0.01em;
	vertical-align: baseline;
}

/* ---------------- Buttons & controls ---------------- */
.tc-tiddler-controls button,
.tc-page-controls button {
	border-radius: 8px;
	transition: background-color .15s ease, color .15s ease, transform .1s ease;
}
.tc-tiddler-controls button:hover,
.tc-page-controls button:hover {
	background-color: rgba(140,120,100,0.12);
}
.tc-tiddler-controls button:active,
.tc-page-controls button:active {
	transform: translateY(1px);
}
.tc-btn-big-green {
	border-radius: 10px;
	padding: 8px 14px;
}

/* ---------------- Inputs & editor (composer-like) ---------------- */
.tc-edit-texteditor,
input[type=text],
input[type=search],
textarea {
	border-radius: 12px;
	border: 1px solid <<colour tiddler-editor-border>>;
	transition: border-color .15s ease, box-shadow .15s ease;
}
.tc-edit-texteditor:focus,
input[type=text]:focus,
input[type=search]:focus,
textarea:focus {
	outline: none;
	border-color: <<colour primary>>;
	box-shadow: 0 0 0 3px rgba(217,119,87,0.20);
}

/* ---------------- Code & preformatted ---------------- */
code {
	border-radius: 6px;
	padding: 0.12em 0.42em;
	font-size: 0.88em;
	background: <<colour code-background>>;
	border: 1px solid <<colour code-border>>;
}
pre {
	border-radius: 12px;
	padding: 16px 18px;
	line-height: 1.55;
	overflow: auto;
	border: 1px solid <<colour pre-border>>;
	background: <<colour pre-background>>;
}
pre code {
	border: none;
	padding: 0;
	background: transparent;
	font-size: 0.9em;
}

/* ---------------- Blockquotes ---------------- */
blockquote {
	border-left: 3px solid <<colour primary>>;
	margin: 1em 0;
	padding: 0.2em 0 0.2em 1.1em;
	font-style: italic;
}

/* ---------------- Tables ---------------- */
.tc-tiddler-body table {
	border-collapse: separate;
	border-spacing: 0;
	border: 1px solid <<colour table-border>>;
	border-radius: 12px;
	overflow: hidden;
}
.tc-tiddler-body table th {
	background: <<colour table-header-background>>;
	font-weight: 700;
	text-align: left;
}
.tc-tiddler-body table th,
.tc-tiddler-body table td {
	border: none;
	border-bottom: 1px solid <<colour table-border>>;
	padding: 8px 12px;
}
.tc-tiddler-body table tr:last-child td { border-bottom: none; }
.tc-tiddler-body table tbody tr:hover td { background: rgba(140,120,100,0.05); }

/* ---------------- Horizontal rule ---------------- */
hr {
	border: none;
	height: 1px;
	background: <<colour table-border>>;
	margin: 1.6em 0;
}

/* ---------------- Sidebar ---------------- */
.tc-sidebar-scrollable { padding-top: 42px; }
.tc-site-subtitle { font-size: 0.9em; letter-spacing: 0.02em; }

.tc-sidebar-lists .tc-tab-buttons button {
	border: none;
	border-radius: 8px;
	margin-right: 4px;
	padding: 5px 12px;
	font-weight: 600;
	background: transparent;
	transition: background-color .15s ease, color .15s ease;
}
.tc-sidebar-lists .tc-tab-buttons button:hover { background: rgba(140,120,100,0.10); }
.tc-sidebar-lists .tc-tab-buttons button.tc-tab-selected { background: rgba(140,120,100,0.14); }

.tc-search input { border-radius: 10px; padding: 6px 10px; }

/* ---------------- Dropdowns & popups ---------------- */
.tc-drop-down {
	border-radius: 12px;
	border: 1px solid <<colour dropdown-border>>;
	box-shadow: 0 12px 30px -12px rgba(60,50,40,0.28);
	padding: 6px;
}
.tc-drop-down a,
.tc-drop-down button,
.tc-drop-down .tc-tab-buttons button { border-radius: 8px; }

/* ---------------- Modals ---------------- */
.tc-modal {
	border-radius: 16px;
	overflow: hidden;
	border: 1px solid <<colour modal-border>>;
	box-shadow: 0 24px 60px -16px rgba(60,50,40,0.40);
}

/* ---------------- Selection ---------------- */
::selection {
	background: <<colour selection-background>>;
	color: <<colour selection-foreground>>;
}

/* ---------------- Scrollbars ---------------- */
* { scrollbar-width: thin; scrollbar-color: rgba(140,120,100,0.4) transparent; }
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
	background: rgba(140,120,100,0.35);
	border-radius: 999px;
	border: 3px solid transparent;
	background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover {
	background: rgba(140,120,100,0.55);
	background-clip: content-box;
}
